"""
author:wjw
分析：贪心+二分查找。和300题类似，不过300是严格递增子序列，该题是非递减子序列。
    时间复杂度：O（nlogn）
"""

import bisect


class Solution:
    def longestObstacleCourseAtEachPosition(self, obstacles):
        n = len(obstacles)
        d = [0]
        ans = []

        for i in range(n):
            index = bisect.bisect(d, obstacles[i])
            if index == len(d):
                d.append(obstacles[i])
            else:
                d[index] = min(d[index], obstacles[i])

            ans.append(index)

        return ans


obstacles = [1, 2, 3, 2]
